function isNumberKey(n){var t=n.which?n.which:event.keyCode;return t>31&&(t<48||t>57)?!1:!0}function checkCardNumber(){var n=$("#cardNumber").val();return isValidValidateHekmatCard(String(n))?($("#validationCardNumber").html(""),!0):($("#validationCardNumber").html("کاربر گرامی ، شماره کارت وارد شده نامعتبر می باشد"),!1)}function checkNationalCode(){var n=$("#nationalCode").val();return nationalCodeValidate(n)?($("#validationNationalCode").html(""),!0):($("#validationNationalCode").html("کاربر گرامی ، کد ملی وارد شده نامعتبر می باشد"),!1)}function checkMobile(){var n=$("#mobile").val();return isValidateMobileNumber(n)?($("#validationMobileNumber").html(""),!0):($("#validationMobileNumber").html("کاربر گرامی ، شماره همراه وارد شده نامعتبر می باشد"),!1)}function checkTellNumber(){var n=$("#tell").val();return isValidateTellNumber(n)?($("#validationTellNumber").html(""),!0):($("#validationTellNumber").html("کاربر گرامی ، شماره تلفن ثابت وارد شده نامعتبر می باشد"),!1)}function isValidateMobileNumber(n){return/^(\+98|0)?9\d{9}$/.test(n)}function isValidateTellNumber(n){return/^0[1-9]{2}[0-9]{8}$/.test(n)}function isValidValidateHekmatCard(n){if(n==="undefined"||n.length!==16||!n.startsWith("08920")||n==="0892012345678912")return!1;let t=0;for(let i=0;i<16;i+=1){const r=Number(n[i]);t+=i%2==0?r*2>9?r*2-9:r*2:r}return t%10==0}$("form").submit(function(n){n.preventDefault()});